args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Windsor_Drive_(film) dbr:Woman_by_Woman:_New_Hope_for_the_Villages_of_India }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?dob1. }
  OPTIONAL { ?director dbp:birthDate ?dob2. }
  BIND(coalesce(?dob1, ?dob2) AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
}
ORDER BY ?birthDate
LIMIT 1

